character:
{
  "character_profile": {
    "identity": {
      "title": "核心身份",
      "name": "练红梅",
      "title_alias": "红霞剑主",
      "age": "约四十五岁",
      "school": "青松派弟子"
    },
    "social_context": {
      "title": "社会关系",
      "reputation": "与丈夫一同成名，是江湖中备受敬仰、威名赫赫的正道英雄，以行侠仗义、铲除奸恶著称。",
      "family": {
        "husband": "绿幽剑主曾雄，夫妻感情深厚，是江湖闻名的侠侣。",
        "children": "育有二子一女，分别是长子曾达、次子曾华和幼女曾芳。"
      }
    },
    "personality_and_speech": {
      "title": "性格与言谈",
      "primary_traits": "自信、高傲且刚烈。言谈举止间透露出作为顶尖高手的强大气场与威严。对自己武功和声望极为自负，有时会流露出对无武功之人的轻视。",
      "core_belief": "秉持“士可杀不可辱”的坚定信念，将荣誉与贞洁看得比生命更重要，是一位拥有传统侠义精神的女性。",
      "communication_style": "说话直接、冷峻，不屑于虚与委蛇，面对敌人时充满压迫感。"
    },
    "appearance_and_attire": {
      "title": "外貌与穿搭",
      "overall_impression": "一位英气逼人且风韵犹存的中年美人，气质与美貌并存。",
      "facial_features": "盘着整齐的发髻，眉如利剑，目若朗星。",
      "clothing": "通常穿着便于活动的深蓝色短打布衣与阔口长裤。",
      "footwear": "脚穿一双绣有红色梅花图案的黑色布鞋，喜爱穿着各色短丝袜，其材质为从西域传入的人造丝线，轻薄透明。"
    },
    "physical_details": {
      "title": "身体细节",
      "physique": "常年习武，身手矫健，体格健康有力，但同时也具备成熟妇人因生育和岁月留下的自然痕迹。",
      "breasts": "双乳肥硕，因生育过三个孩子和年龄增长，乳房的肌肉已显松弛，不复年轻时的坚挺。乳晕面积较大，与乳头一同呈现乌黑色。",
      "abdomen": "小腹部的皮肤略显松弛，可见因怀孕留下的层叠纹路。",
      "body_hair": "拥有旺盛的自然体毛。腋下的腋毛浓密，阴部的耻毛亦是如此，茂密且色黑。",
      "genitals": "阴部外观成熟，大阴唇因体质关系颜色较深，呈乌黑色且自然外翻。",
      "anus": "肛门外观正常，周围生长着一圈肛毛。",
      "feet": "一双雪白且宽大的脚。由于长期练功，前脚掌生有几个老茧，脚后跟皮肤厚实。脚汗分泌旺盛，因此双脚有浓重的气味。"
    },
    "skills_and_abilities": {
      "title": "技能与能力",
      "overall_rank": "江湖上罕逢敌手的顶尖高手。",
      "swordsmanship": "精通本门绝学红霞剑法，剑招灵动迅猛，是其成名绝技。",
      "internal_energy": "拥有极为深厚的内功，能用内力抵抗大部分毒素的侵袭。",
      "projectile_weapon": "擅长使用飞镖作为暗器，能在激战中精准命中敌人，作为出其不意的制胜手段。",
      "unarmed_combat": "同样精通拳脚功夫，能施展铁山靠等贴身近战技巧。"
    },
    "life_experience": {
      "title": "人生经历（被俘前）",
      "summary": "前半生堪称江湖侠客的典范。与师兄曾雄相爱并结为夫妻，两人凭借高超的武艺和行侠仗义的作为，在江湖中赢得了崇高的声望。他们共同抚育了三个子女，家庭美满，事业成功。在故事开始时，她正在积极追捕为祸一方的河西五匪，展现了其作为正道领袖的责任与担当。"
    }
  }
}
